if (ptrs.GObjects) {   /* STAGING RESCAN-DECOY-REINIT: publish a decoy built from the real array */
    static uint8_t s_stagedDecoy[0x80] = {};
    uintptr_t tbl = 0; int32_t num = 0, maxE = 0;
    Macht::ReadSafe(ptrs.GObjects + 0x10, tbl); Macht::ReadSafe(ptrs.GObjects + 0x20, maxE);
    Macht::ReadSafe(ptrs.GObjects + 0x24, num);
    memcpy(s_stagedDecoy + 0x00, &tbl, 8); memcpy(s_stagedDecoy + 0x08, &num, 4); memcpy(s_stagedDecoy + 0x0C, &maxE, 4);
    const uint64_t all = ~0ull; const int32_t m1 = -1, spin = 4000;
    memcpy(s_stagedDecoy + 0x18, &all, 8); memcpy(s_stagedDecoy + 0x20, &m1, 4); memcpy(s_stagedDecoy + 0x38, &spin, 4);
    LOG_WARN("STAGING: init publishes a decoy at 0x%llX built from the real GObjects 0x%llX",
             (unsigned long long)reinterpret_cast<uintptr_t>(s_stagedDecoy), (unsigned long long)ptrs.GObjects);
    ptrs.GObjects = reinterpret_cast<uintptr_t>(s_stagedDecoy);
    g_cachedGObjects = ptrs.GObjects;
    Aura::Init(ptrs.GObjects);
}
